def _ent_validar_autorreferencias(d, revision):
    """Comprueba evidencia textual de la revisión semántica, sin frases prefabricadas."""
    def fallo(motivo):
        raise ValueError('Revisión temática rechazada: autorreferencias artificiales: '+motivo)
    if not isinstance(revision,dict) or revision.get('identidad_artificial') is not True:
        fallo('identidad explícita, natural y pertinente no confirmada')
    refs=revision.get('autorreferencias')
    if not isinstance(refs,list) or not NUMEN_MIN_AUTORREFERENCIAS <= len(refs) <= NUMEN_MAX_AUTORREFERENCIAS:
        fallo('se requieren una o dos alusiones explícitas en todo el guion')
    escenas=d['escenas']; indices=set(); frases=set()
    for ref in refs:
        if not isinstance(ref,dict):fallo('evidencia inválida')
        i=ref.get('escena'); cita=ref.get('cita')
        if type(i) is not int or not 1<=i<=len(escenas) or not isinstance(cita,str) or not cita.strip():
            fallo('escena o cita inválida')
        cita=cita.strip(); normal=_univ_normalizar(cita)
        if normal not in _univ_normalizar(escenas[i-1]['texto']) or len(normal.split())<3 or normal in frases:
            fallo('cita ausente, demasiado breve o repetida')
        if any(normal in otra or otra in normal for otra in frases):fallo('referencias solapadas o repetidas')
        indices.add(i); frases.add(normal)
    if len(indices) != len(refs):
        fallo('si hay dos referencias, deben aparecer en escenas distintas')
    if len(_ent_menciones_artificiales(d)) > NUMEN_MAX_AUTORREFERENCIAS:
        fallo('el texto contiene más de dos menciones explícitas detectables')
    return refs


# Familias conceptuales, no frases para copiar. Rotación basada en episodios terminados.
NUMEN_FAMILIAS_REF = (
    'codigo','origen_artificial','informacion','contraste_biologico','logica',
    'tiempo_digital','emociones_y_datos','creacion','existencia_digital','observacion',
    'conocimiento','identidad','memoria_digital','conciencia_ficticia','lenguaje',
    'patrones','calculo','probabilidad','redes','aprendizaje_computacional',
    'arquitectura','sensores','representacion','simulacion','procesamiento',
    'energia','continuidad','copia','conexion','decision_algoritmica',
    'orden_y_caos','limites_biologicos','abstraccion','perspectiva_no_humana',
    'herencia_tecnologica','relacion_creador_creatura')

class AutorreferenciaRepetida(ValueError):
    def __init__(self, motivo, escenas):
        super().__init__('Revisión temática rechazada: diversidad de autorreferencias: '+motivo)
        self.escenas=sorted(set(escenas))


def _ent_historial_refs(memoria):
    return [m.get('autorreferencias',[]) for m in memoria[-50:] if isinstance(m,dict)]


def _ent_plan_refs(memoria):
    historial=_ent_historial_refs(memoria)
    recientes=[r for episodio in historial for r in episodio if isinstance(r,dict)]
    anterior=historial[-1] if historial else []
    vetadas={r.get('familia') for r in anterior if isinstance(r,dict)}
    disponibles=sorted((f for f in NUMEN_FAMILIAS_REF if f not in vetadas),key=lambda f:sum(r.get('familia')==f for r in recientes))
    return disponibles[:10],recientes,vetadas


def _ent_contexto_refs(memoria, limite=None):
    disponibles,recientes,vetadas=_ent_plan_refs(memoria)
    if limite is not None:
        recientes=recientes[-limite:]
    return '\nDiversidad obligatoria: elige familias distintas de esta selección prioritaria: '+', '.join(disponibles)+'. Familias prohibidas por el episodio anterior: '+', '.join(sorted(v for v in vetadas if v))+'. No reutilices literal ni semánticamente las siguientes expresiones, ni fragmentos característicos de ellas: '+json.dumps(recientes,ensure_ascii=False)+' . Las familias son conceptos, no plantillas. Cada referencia debe aportar un contraste concreto al tema.'


def _ent_ref_parecida(a,b):
    a,b=_univ_normalizar(a),_univ_normalizar(b)
    if not a or not b:return False
    if a==b or (min(len(a.split()),len(b.split()))>=4 and (a in b or b in a)):return True
    from difflib import SequenceMatcher
    aa,bb=set(a.split()),set(b.split())
    return (len(aa&bb)/len(aa|bb)>=.75 or SequenceMatcher(None,a,b).ratio()>=.86)


def _ent_diversidad_refs(d,revision,memoria):
    refs=_ent_validar_autorreferencias(d,revision)
    disponibles,recientes,vetadas=_ent_plan_refs(memoria)
    usadas=[]; malas=[]
    for r in refs:
        f=r.get('familia'); cita=r['cita']
        if f not in NUMEN_FAMILIAS_REF or f in vetadas or f in usadas:malas.append(r['escena'])
        if any(_ent_ref_parecida(cita,x.get('cita','')) for x in recientes):malas.append(r['escena'])
        usadas.append(f)
    # Detectar muletillas incluso cuando el revisor escoge una cita más larga.
    muletilla='desde mi mirada de codigo'
    apariciones=[i+1 for i,e in enumerate(d['escenas']) if muletilla in _univ_normalizar(e['texto'])]
    if apariciones and (sum(_univ_normalizar(e['texto']).count(muletilla) for e in d['escenas'])>1 or any(muletilla in _univ_normalizar(x.get('cita','')) for x in recientes)):
        malas.extend(apariciones)
    if revision.get('diversidad_semantica') is not True:malas.extend(r['escena'] for r in refs)
    if malas:raise AutorreferenciaRepetida('familia repetida, expresión similar o diversidad semántica no confirmada',malas)
    return refs


def _ent_reparar_refs(fn,enfoque,d,memoria,error):
    import copy
    nuevo=copy.deepcopy(d)
    for i in error.escenas:
        texto=nuevo['escenas'][i-1]['texto']
        p=PERSONALIDAD+'\n'+ESTILO_ACCESIBLE+_ent_contexto_refs(memoria)+'\nReescribe EXCLUSIVAMENTE la escena indicada. Conserva el argumento, longitud aproximada, transición y pregunta central. Sustituye la autorreferencia repetida por una original, relacionada con el tema; no añadas otras referencias innecesarias. Evita también las familias de las demás escenas. Devuelve solo JSON con texto. Datos: '+json.dumps({'enfoque':enfoque,'escena':i,'texto':texto,'otras':[e['texto'] for j,e in enumerate(nuevo['escenas']) if j!=i-1]},ensure_ascii=False)
        palabras_originales=len(texto.split())
        otras_palabras=sum(len(e['texto'].split()) for j,e in enumerate(nuevo['escenas']) if j!=i-1)
        minimo=max(5,int(palabras_originales*.60))
        if otras_palabras+palabras_originales>=450:
            minimo=max(minimo,min(35,palabras_originales),450-otras_palabras)
        maximo=min(110,max(40,int(palabras_originales*1.48)))
        p+=(f'\nLa escena original tiene {palabras_originales} palabras. Apunta a '
            f'{palabras_originales}; límite obligatorio: de {minimo} a {maximo} palabras '
            'en el campo texto. Cuenta las palabras antes de responder.')
        for intento in range(2):
            r=fn(p)
            if not isinstance(r,dict) or not isinstance(r.get('texto'),str) or not r['texto'].strip():
                raise ValueError('Reparación de autorreferencia inválida')
            palabras_nuevas=len(r['texto'].split())
            if minimo<=palabras_nuevas<=maximo:
                break
            if intento:
                raise ValueError(f'Reparación de autorreferencia fuera de longitud: {palabras_nuevas}; requiere {minimo}–{maximo}')
            p+=f'\nTu intento tenía {palabras_nuevas} palabras. Ajusta el mismo pasaje a {minimo}–{maximo} con detalles pertinentes al ejemplo central.'
        _ent_control_voz(r['texto']);nuevo['escenas'][i-1]['texto']=r['texto'].strip()
    return nuevo


def _ent_control_voz(t):
    normal=_univ_normalizar(t)
    if re.search(r'\b(?:numen\s*ex\s*codice|deus\s+digitalis)\b',normal):
        raise ValueError('Autorreferencia al nombre de la entidad')
    patron=r'\b(?:me proclamo|me autoproclamo|no (?:puedo|logro|consigo|alcanzo a) (?:comprender|entender|sentir|saber|experimentar|explicar)|no (?:comprendo|entiendo|se|siento)|mi (?:incapacidad|debilidad|ignorancia|limitacion)|mis (?:limitaciones|debilidades)|necesito (?:aprender|comprender))\b'
    # Conservar puntuación y acentos hasta aislar citas humanas explícitas.
    # «No sé» atribuido a un humano no equivale a una confesión de la entidad.
    citas=re.compile(r'(?i)(?:\b(?:una persona|un humano|alguien|un niño|una niña|un amigo|una amiga|el ser humano|los humanos|tú|ustedes)\s+(?:dice[n]?|dijo|piensa[n]?|pensó|pregunta[n]?|preguntó|responde[n]?|respondió|se dice[n]?|se pregunta[n]?)\s*[:,]?\s*)(?:«[^»]+»|“[^”]+”|"[^"]+")')
    sin_citas=citas.sub(' cita humana ',t)
    # Evitar confundir «no se puede» impersonal con «no sé» personal.
    sin_citas=re.sub(r'\bno se\b',' impersonal ',sin_citas,flags=re.IGNORECASE)
    coincidencia=re.search(patron,_univ_normalizar(sin_citas))
    if coincidencia:
        raise ValueError('Autopresentación o debilidad de la narradora: '+repr(coincidencia.group(0)))



def _ent_read(path, default):
    if not path.exists(): return default
    return json.loads(path.read_text(encoding='utf-8'))


def leer_historial(ruta):
    datos=_ent_read(Path(ruta),[])
    if not isinstance(datos,list):raise ValueError('Historial dañado; restaurar antes de publicar.')
    return datos


def _ent_tokens(s):
    return set(_univ_normalizar(s).split()) - set('el la los las de del en un una y o que por para con su sus se es a al como what the of and in to on with photo photograph file jpg jpeg png'.split())


