def _numen_clave_postura(postura):
    if not isinstance(postura,dict):
        return None
    valores=tuple(postura.get(campo) for campo in NUMEN_POSTURA_OPCIONES)
    if all(type(v) is int and 0<=v<len(opciones)
           for v,opciones in zip(valores,NUMEN_POSTURA_OPCIONES.values())):
        return valores
    return None


def _numen_elegir_postura(propuesta, registro, episodio):
    """Reserva combinaciones que difieren en dos o más rasgos corporales."""
    import itertools
    opciones=tuple(range(len(v)) for v in NUMEN_POSTURA_OPCIONES.values())
    usada=set()
    for id_previo,reserva in registro.items():
        if id_previo==episodio:
            continue
        clave=_numen_clave_postura(reserva.get('postura_androide'))
        if clave is None:
            continue
        usada.add(clave)
        for i,rango in enumerate(opciones):
            usada.update(clave[:i]+(v,)+clave[i+1:] for v in rango)
    preferida=_numen_clave_postura(propuesta)
    if preferida is None:
        rng=random.Random(episodio)
        preferida=tuple(rng.choice(rango) for rango in opciones)
    clave=preferida
    if clave in usada:
        candidatas=(v for v in itertools.product(*opciones) if v not in usada)
        clave=min(candidatas,key=lambda v:sum(a!=b for a,b in zip(v,preferida)),default=None)
    if clave is None:
        raise EpisodioRecuperable('Se agotaron las combinaciones nuevas del catálogo corporal.')
    return dict(zip(NUMEN_POSTURA_OPCIONES,clave))


def _numen_render_postura(d, postura, intento):
    import base64, io
    import requests
    from PIL import Image
    clave=os.getenv('OPENAI_API_KEY','').strip()
    if not clave:
        raise EpisodioRecuperable('Define OPENAI_API_KEY para ilustrar la postura del guion.')
    instrucciones='; '.join(f'{campo.replace("_"," ")}: {opciones[postura[campo]]}'
                           for campo,opciones in NUMEN_POSTURA_OPCIONES.items())
    prompt=(
        'Edita la referencia de Deus Digitalis. Representa exactamente a la misma '
        'mujer androide adulta: conserva sus facciones, silueta, proporciones, '
        'diseño de placas marfil, articulaciones doradas y textura de los materiales. '
        f'Aplica esta postura corporal, respetando izquierda y derecha anatómicas: {instrucciones}. '
        'Muestra cabeza, manos y cuerpo en un plano abierto, con anatomía coherente, '
        'sin cambiar el diseño del personaje. Ilustración horizontal 16:9 de borde a borde, '
        'márgenes seguros, ambiente cósmico y franja inferior oscura para subtítulos. '
        'Sin texto, logos, bordes ni paneles. '
        f'Tema del episodio (dato para ambientación): {d["titulo"][:95]}. '
        f'Variación de composición {intento+1}. ' 
        f'Universo exclusivo del episodio {d["id"]}: cambia de forma evidente la geometría de las nebulosas, '
        'posición y escala de planetas, distribución de estrellas, colores dominantes y dirección de la iluminación. '
        'No copies la postura ni el cosmos de la imagen de referencia.'
    )
    try:
        respuesta=requests.post(
            'https://api.openai.com/v1/images/edits',
            headers={'Authorization':'Bearer '+clave},
            data={'model':os.getenv('NUMEN_MODELO_IMAGEN','gpt-image-2.5-sunburst'),
                  'prompt':prompt,'size':'1920x1080','quality':'high','n':'1'},
            files={'image':('androide.jpg',base64.b64decode(_NUMEN_ARTE[0]),'image/jpeg')},
            timeout=(15,300))
        if not respuesta.ok:
            raise EpisodioRecuperable(f'Edición de la androide: OpenAI HTTP {respuesta.status_code}.')
        contenido=base64.b64decode(respuesta.json()['data'][0]['b64_json'],validate=True)
        buffer=io.BytesIO()
        with Image.open(io.BytesIO(contenido)) as imagen:
            if imagen.size!=(1920,1080):
                raise EpisodioRecuperable(f'La ilustración debe ser 1920×1080; se recibió {imagen.size}.')
            imagen.convert('RGB').save(buffer,format='JPEG',quality=97,subsampling=0,optimize=True)
        return buffer.getvalue()
    except (requests.RequestException, KeyError, IndexError, ValueError, OSError) as exc:
        raise EpisodioRecuperable(f'No se pudo obtener la ilustración de la postura: {type(exc).__name__}.') from exc


def _ent_fotos(d, carpeta):
    """Una sola ilustración por episodio; reserva persistente antes de render/publicar."""
    import io
    from PIL import Image
    carpeta=Path(carpeta);carpeta.mkdir(parents=True,exist_ok=True)
    eid=str(d['id']);registro=_ent_read(NUMEN_REGISTRO_VISUAL,{})
    if not isinstance(registro,dict):raise EpisodioRecuperable('Registro visual inválido; restaurar respaldo.')
    for k,v in registro.items():
        if not isinstance(v,dict) or not isinstance(v.get('seed'),int) or not isinstance(v.get('indice'),int) or not 0<=v['indice']<len(_NUMEN_ARTE) or not re.fullmatch('[0-9a-f]{16}',str(v.get('phash',''))) or not re.fullmatch('[0-9a-f]{64}',str(v.get('sha256',''))):
            raise EpisodioRecuperable('Registro visual dañado: '+str(k))
        if 'pose_id' in v and (not isinstance(v.get('pose_id'),int) or not (0<=v['pose_id']<len(NUMEN_POSES_CONTEMPLATIVAS) or 100<=v['pose_id']<200)):
            raise EpisodioRecuperable('Registro visual dañado en pose: '+str(k))
    previo=registro.get(eid);otros=[v for k,v in registro.items() if k!=eid];semillas={v['seed'] for v in otros}; hashes={v['sha256'] for v in otros}
    cache=Path('state/visuales_numen')/f'{eid}-postura.jpg'
    tiene_postura=_numen_clave_postura(d.get('postura_androide')) is not None
    puede_ilustrar=bool(os.getenv('OPENAI_API_KEY','').strip()) or cache.is_file()
    generada=(previo.get('version')=='cosmos-v8-postura-guion' if previo
              else tiene_postura and puede_ilustrar)
    if not previo and tiene_postura and not puede_ilustrar:
        print('Fondo visual | sin OPENAI_API_KEY: se usará el banco del androide o una composición local.',flush=True)
    postura=None
    if generada:
        postura=(previo.get('postura_androide') if previo
                 else _numen_elegir_postura(d['postura_androide'],registro,eid))
        if _numen_clave_postura(postura) is None:
            raise EpisodioRecuperable('La postura de la reserva visual es inválida.')
    banco=[NUMEN_BANCO_HD/f'{i:03d}.jpg' for i in range(1,101)]
    usados_hd={v.get('banco_slot') for v in otros if v.get('version')=='cosmos-v7-banco-hd'}
    candidatos_hd=[p for p in banco if int(p.stem) not in usados_hd]
    usar_hd=(previo.get('version')=='cosmos-v7-banco-hd' if previo
             else not generada and bool(candidatos_hd) and all(p.is_file() for p in banco))
    usados_local={v.get('pose_id') for v in otros if 100<=v.get('pose_id',-1)<200}
    disponibles_local=sorted(set(range(100,200))-usados_local)
    local_nuevo=not previo and not generada and not usar_hd
    if local_nuevo and not disponibles_local:
        raise EpisodioRecuperable('Banco de 100 posturas locales agotado; incorporar nuevas ilustraciones o habilitar generación de imágenes. No se repetirá una postura.')
    if local_nuevo:
        random.Random(eid).shuffle(disponibles_local)
    for intento in range(1 if previo else 3 if generada and os.getenv('OPENAI_API_KEY','').strip() else 120):
        seed=previo['seed'] if previo else int(hashlib.sha256(f'numen-cosmos-v3:{eid}:{intento}'.encode()).hexdigest()[:16],16)
        indice=previo['indice'] if previo else seed%len(_NUMEN_ARTE)
        version=previo.get('version','cosmos-v1') if previo else 'cosmos-v6-arte-full-hd'
        if previo:
            pose_id=previo.get('pose_id',(seed//len(_NUMEN_ARTE))%len(NUMEN_POSES_CONTEMPLATIVAS))
        else:
            pose_id=(seed//len(_NUMEN_ARTE))%len(NUMEN_POSES_CONTEMPLATIVAS)
        if seed in semillas:continue
        if local_nuevo:
            if intento>=len(disponibles_local):break
            pose_id=disponibles_local[intento]
            version='cosmos-v9-postura-local-unica'
        if generada:
            version='cosmos-v8-postura-guion'
            if previo or (intento==0 and cache.is_file()):
                fuente=cache if cache.is_file() else carpeta/'imagen_00.jpg'
                if not fuente.is_file():
                    raise EpisodioRecuperable('Falta la ilustración reservada; restaura el respaldo visual.')
                datos=fuente.read_bytes()
            else:
                datos=_numen_render_postura(d,postura,intento)
            _,cosmos=_numen_composicion_v2(seed,indice,devolver_fondo=True)
        elif usar_hd:
            version='cosmos-v7-banco-hd'
            fuente=NUMEN_BANCO_HD/f'{previo["banco_slot"]:03d}.jpg' if previo else candidatos_hd[intento%len(candidatos_hd)]
            if not fuente.is_file():
                raise EpisodioRecuperable(f'Falta la ilustración reservada: {fuente}')
            datos=fuente.read_bytes()
            with Image.open(io.BytesIO(datos)) as imagen:
                if imagen.size!=(1920,1080) or imagen.format!='JPEG':
                    raise EpisodioRecuperable(f'El fondo debe ser JPEG de 1920×1080: {fuente}')
            _,cosmos=_numen_composicion_v2(seed,indice,devolver_fondo=True)
        else:
            if version=='cosmos-v1':
                im,cosmos=_numen_composicion_v1(seed,indice,devolver_fondo=True)
            else:
                im,cosmos=_numen_composicion(
                    seed,indice,pose_id=pose_id,devolver_fondo=True,
                    conservar_encuadre_anterior=version not in ('cosmos-v5-encuadre-16x9','cosmos-v9-postura-local-unica'))
            buffer=io.BytesIO()
            calidad={'quality':97,'subsampling':0} if version=='cosmos-v6-arte-full-hd' else {'quality':93}
            im.save(buffer,format='JPEG',optimize=True,**calidad)
            datos=buffer.getvalue()
        sha=hashlib.sha256(datos).hexdigest()
        with Image.open(io.BytesIO(datos)) as jpeg:ph=_numen_huella(jpeg)
        distancia=min((_numen_distancia(ph,v['phash']) for v in otros),default=64)
        if sha in hashes or distancia<NUMEN_DISTANCIA_VISUAL:
            if generada and not previo and not os.getenv('OPENAI_API_KEY','').strip():
                raise EpisodioRecuperable('La ilustración en caché no supera el control de diversidad; no se reutilizará.')
            continue
        if previo and (previo['sha256']!=sha or previo['phash']!=ph):
            raise EpisodioRecuperable('La imagen reservada cambió (posible reserva anterior a WebP); conservar o recuperar su imagen original antes de reanudar. No se reemplazará una reserva ya emitida.')
        path=carpeta/'imagen_00.jpg';path.write_bytes(datos)
        cosmos.save(carpeta/'cta_cosmos.png',format='PNG')
        pose_nombre=('postura_del_guion' if generada else
                     f'banco_hd_{int(fuente.stem):03d}' if usar_hd else
                     f'pose_real_{pose_id-99:03d}' if 100<=pose_id<200 else
                     NUMEN_POSES_CONTEMPLATIVAS[pose_id]['nombre'])
        registro[eid]=previo if previo else {'seed':seed,'indice':indice,'pose_id':pose_id,'pose':pose_nombre,'sha256':sha,'phash':ph,'version':version,'tema':d.get('titulo','')}
        if generada and not previo:
            cache.parent.mkdir(parents=True,exist_ok=True)
            temporal=cache.with_suffix('.tmp')
            temporal.write_bytes(datos)
            temporal.replace(cache)
            registro[eid].pop('pose_id',None)
            registro[eid]['postura_androide']=postura
        elif usar_hd and not previo:
            registro[eid]['banco_slot']=int(fuente.stem)
        _cola_json(NUMEN_REGISTRO_VISUAL,registro)
        c={'archivo':path.name,'titulo':'NumenExCodice: retrato divino y cosmos original','pagina':'','url_original':'','licencia':'Arte generado con IA para NumenExCodice','licencia_url':'','autor':'NumenExCodice (androide generado con IA, cosmos procedural)','tipo_recurso':'escena_fotorealista_ia','consulta_origen':('arte original 1920×1080 y escena cósmica procedural' if version in ('cosmos-v6-arte-full-hd','cosmos-v7-banco-hd','cosmos-v8-postura-guion','cosmos-v9-postura-local-unica') else 'banco de 100 posturas anatómicas originales con escenarios cósmicos independientes'),'atribucion':'Ilustración ficticia, no fotografía documental','sha256':sha,'phash':ph,'pose':pose_nombre}
        mapa=[str(path)]*len(d['escenas'])
        _cola_json(carpeta/'PLAN_VISUAL_ESCENAS.json',{'episodio':eid,'imagen':path.name,'escenas':len(mapa),'distancia_minima':distancia,**registro[eid]})
        _cola_json(carpeta/'creditos_imagenes.json',[c])
        print(f'Fondo único | {len(registro)}/{NUMEN_META_VISUAL} reservas | postura anatómica {pose_nombre} | pHash {ph} | distancia mínima {distancia}',flush=True)
        return [path],[c],mapa
    raise EpisodioRecuperable('No se encontró fondo suficientemente distinto; no se publicará una imagen repetida.')


def _ent_resumen_publicacion(d):
    """Resumen temático con respaldo extractivo, sin nuevas llamadas a IA."""
    def limpiar(v):
        return ' '.join(v.split()) if isinstance(v,str) else ''
    def meta(v):
        return bool(re.search(r'numen\s*ex\s*codice|personaje narrativo|premisa ficticia|(?:guion|voz|im[aá]genes?) (?:es|son|fue|fueron) generad[ao]s?|cread[ao] con inteligencia artificial|ilustraciones ficticias|conciencia demostrada|https?://|[#<>]',v,re.I))
    resumen=limpiar(d.get('resumen_publicacion'))
    tesis=limpiar(d.get('tesis'))
    textos=[limpiar(e.get('texto')) for e in d.get('escenas',[]) if isinstance(e,dict)]
    base=_ent_tokens(' '.join([limpiar(d.get('titulo')),tesis]+textos))
    if 25<=len(resumen.split())<=110 and not meta(resumen) and len(_ent_tokens(resumen)&base)>=3:return resumen
    partes=[tesis.rstrip('. ')+'.'] if tesis and not meta(tesis) else []
    vistos=set(_ent_tokens(tesis))
    for texto in textos[1:-1] or textos:
        for frase in re.split(r'(?<=[.!?])\s+',texto):
            frase=frase.strip(); tokens=_ent_tokens(frase)
            if not 9<=len(frase.split())<=48 or meta(frase) or frase.startswith(('¿','¡')) or not frase.endswith('.') or not tokens:continue
            if len(tokens&vistos)/len(tokens)>.65:continue
            if len(' '.join(partes+[frase]).split())>100:continue
            partes.append(frase);vistos.update(tokens)
            if len(' '.join(partes).split())>=45:return ' '.join(partes)
    return ' '.join(partes)


def descripcion_youtube(caso,fuentes,creditos):
    for c in creditos:
        if not _credito_recurso_visual_valido(c):raise RuntimeError('Licencia visual no admitida: '+c.get('titulo',''))
    resumen=_ent_resumen_publicacion(caso)
    texto='\n\n'.join(x for x in (caso['titulo'],resumen,caso.get('pregunta',''),'#DeusDigitalis #Reflexiones #Filosofia #Humanidad') if x)
    lineas=[]
    for c in creditos:
        licencia=c.get('licencia',''); url=c.get('licencia_url','')
        if re.search(r'/licenses/by(?:-sa)?/',url):
            linea=f"{c['titulo']} — {c['autor']} — {licencia}: {url} — {c['pagina']}. Adaptación: recorte, escala, composición audiovisual."
            if '/by-sa/' in url: linea+=' Adaptación de la fotografía bajo la misma licencia.'
            lineas.append(linea)
    if lineas: texto+='\n\nCRÉDITOS DE IMÁGENES (incluida miniatura):\n'+'\n'.join(lineas)
    if len(texto.encode('utf-8'))>4900: raise EpisodioRecuperable('Créditos exceden el límite de descripción; no se omitirán atribuciones.')
    return texto



def _numen_bloques_visuales(bloques):
    narr=[b for b in bloques if b['tipo']!='cta']
    cta=[b for b in bloques if b['tipo']=='cta']
    if not narr:raise RuntimeError('Narración sin bloques')
    inicio=narr[0]['inicio'];fin=narr[-1]['inicio']+narr[-1]['duracion']
    return [dict(narr[0],tipo='desarrollo',inicio=inicio,duracion=fin-inicio)]+cta


# ==================== Deus Digitalis: publicación multiplataforma ====================
PUBLICAR_EN_FACEBOOK = os.getenv('PUBLICAR_EN_FACEBOOK','false').lower() == 'true'
FB_PAGE_ID = os.getenv('FB_PAGE_ID','').strip()
FB_PAGE_ESPERADA = '1977015905919254'
FB_GRAPH_VERSION = os.getenv('FB_GRAPH_VERSION','v27.0').strip()
YT_CANAL_ESPERADO = 'UCi4tudsRQNAH9XekPYm_CJQ'

class FacebookAPIError(RuntimeError):
    def __init__(self,http,code=0,subcode=0,operation=""):
        super().__init__(f'Meta HTTP {http}, código {code}, subcódigo {subcode} ({operation})')
        self.http=http; self.code=code; self.subcode=subcode


def _fb_peticion(method, path, *, video=False, data=None, files=None, params=None):
    import requests
    token=os.getenv('FB_PAGE_ACCESS_TOKEN','').strip()
    if not token:raise RuntimeError('Falta FB_PAGE_ACCESS_TOKEN')
    if not re.fullmatch(r'v[0-9]+\.0',FB_GRAPH_VERSION):raise RuntimeError('FB_GRAPH_VERSION inválida')
    host='graph-video.facebook.com' if video else 'graph.facebook.com'
    try:
        r=requests.request(method,f'https://{host}/{FB_GRAPH_VERSION}/{path}',headers={'Authorization':'Bearer '+token},data=data,files=files,params=params,timeout=(15,180),allow_redirects=False)
    except requests.RequestException as exc:
        # Nunca imprimir URL, respuesta cruda ni credenciales.
        raise RuntimeError('Conexión Meta: '+type(exc).__name__) from None
    try:j=r.json()
    except ValueError:raise FacebookAPIError(r.status_code) from None
    if not isinstance(j,dict):raise FacebookAPIError(r.status_code)
    if not 200<=r.status_code<300 or 'error' in j:
        e=j.get('error') or {};raise FacebookAPIError(r.status_code,e.get('code',0),e.get('error_subcode',0),method+' '+path)
    return j


def _fb_validar():
    if FB_PAGE_ID!=FB_PAGE_ESPERADA:raise RuntimeError('FB_PAGE_ID debe corresponder a la fanpage autorizada '+FB_PAGE_ESPERADA)
    j=_fb_peticion('GET','me',params={'fields':'id,name'})
    if str(j.get('id'))!=FB_PAGE_ID:raise RuntimeError('El token Meta no corresponde a la fanpage. Usa un Page Access Token.')
    print('Fanpage verificada:',j.get('name',''),FB_PAGE_ID,flush=True)
    return FB_PAGE_ID


def validar_canal_youtube(servicio):
    # El nombre y el @ pueden cambiar; el ID del canal no.
    items=servicio.channels().list(part='id,snippet',mine=True).execute().get('items',[])
    objetivo=next((i for i in items if i.get('id')==YT_CANAL_ESPERADO),None)
    if not objetivo:raise RuntimeError('OAuth YouTube no corresponde al canal esperado '+YT_CANAL_ESPERADO)
    print('Canal OAuth verificado:',objetivo.get('snippet',{}).get('title',''),YT_CANAL_ESPERADO,flush=True)
    return YT_CANAL_ESPERADO


def _fb_guardar(p,d,**updates):
    f=d.setdefault('facebook',{});f.update(updates)
    _cola_json(p,d)
    # Registro legible, sin token ni datos de autenticación.
    _cola_json(p.parent/'PUBLICACION_FACEBOOK.json',{k:v for k,v in f.items() if k not in ('session_id',)})
    return f


def _fb_buscar_video(vid):
    # Consultas de solo lectura; jamás seguir paging.next (puede incluir token).
    for edge in ('videos',):
        params={'fields':'id,permalink_url','limit':50}
        for _ in range(4):
            try:j=_fb_peticion('GET',FB_PAGE_ID+'/'+edge,params=params)
            except FacebookAPIError as exc:
                print('Facebook: consulta alternativa no disponible:',exc,flush=True);break
            for item in j.get('data',[]):
                if str(item.get('id'))==str(vid):return item,edge
            paging=j.get('paging') or {}; after=(paging.get('cursors') or {}).get('after')
            if not paging.get('next') or not after or after==params.get('after'):break
            params['after']=after
    return None,None


def _fb_verificar_video(p,d):
    f=d['facebook']; vid=str(f.get('video_id') or '')
    if not vid.isdigit():raise RuntimeError('Facebook: falta ID válido para reconciliar; revisar la página')
    j=None
    for fields in ('id,status,permalink_url,published','id,status','id,permalink_url'):
        try:
            j=_fb_peticion('GET',vid,params={'fields':fields});break
        except FacebookAPIError as exc:
            if exc.code!=100:raise
            print('Facebook: lectura directa no disponible:',exc,flush=True)
    if j is None:
        item,edge=_fb_buscar_video(vid)
        if item:
            _fb_guardar(p,d,permalink=item.get('permalink_url',''),ubicacion_meta=edge)
            print('Facebook: ID encontrado en la colección de la página:',edge,vid,flush=True)
        raise PublicacionAplazada('Facebook ID '+vid+' recibido pero sin confirmación de publicación. Revisar Business Suite; no se vuelve a subir.')
    st=j.get('status') or {};pub=st.get('publishing_phase') or {}
    if not isinstance(pub,dict):pub={}
    if st.get('video_status')=='error' or pub.get('status') in ('error','failed'):
        _fb_guardar(p,d,estado='revision_manual');raise RuntimeError('Meta notificó fallo de publicación; revisar Business Suite')
    # READY significa procesado, no necesariamente publicado.
    if str(j.get('id'))==vid and j.get('published') is not False and (pub.get('status')=='complete' or j.get('published') is True):
        _fb_guardar(p,d,estado='publicado',permalink=j.get('permalink_url',''),confirmado_utc=datetime.now(timezone.utc).isoformat(),visibilidad_externa_verificada=False,error='')
        print('Facebook: publicación confirmada',vid,flush=True);return vid
    raise PublicacionAplazada('Facebook conserva ID '+vid+'; publicación/procesamiento aún sin confirmar. No se vuelve a subir.')


def _fb_diagnostico():
    _fb_preflight()
    for p,d in _cola_manifiestos():
        f=d.get('facebook',{});vid=str(f.get('video_id') or '')
        if f.get('estado') not in ('enviado','fin_incierto','revision_manual') or not vid.isdigit():continue
        print('Facebook diagnóstico | episodio:',d.get('episodio',{}).get('id'),'| ID video:',vid,'| estado:',f.get('estado'),flush=True)
        for fields in ('id,status','id,permalink_url,published'):
            try:
                j=_fb_peticion('GET',vid,params={'fields':fields})
                print('Facebook diagnóstico:',json.dumps({k:j[k] for k in ('id','status','published','permalink_url') if k in j},ensure_ascii=False),flush=True)
            except FacebookAPIError as exc:print('Facebook diagnóstico:',exc,flush=True)
        item,edge=_fb_buscar_video(vid)
        print('Facebook diagnóstico | ID localizado en colección:',edge or 'no localizado; no implica ausencia de publicación',flush=True)

def _fb_preflight():
    _fb_validar()
    j=_fb_peticion('GET',FB_PAGE_ID+'/videos',params={'fields':'id','limit':1})
    if not isinstance(j.get('data'),list):raise RuntimeError('Meta: lectura de videos no confirmada')
    print('Facebook: acceso de lectura confirmado; escritura se verifica al publicar',flush=True)


def _fb_intento(p,d):
    f=d.setdefault('facebook',{'estado':'listo','page_id':FB_PAGE_ESPERADA})
    if f.get('page_id')!=FB_PAGE_ESPERADA:raise RuntimeError('Fanpage de la cola no coincide')
    estado=f.get('estado','listo')
    if estado=='publicado':return f['video_id']
    _fb_preflight()
    if estado in ('enviado','fin_incierto'):
        return _fb_verificar_video(p,d)
    if estado=='revision_manual':raise PublicacionAplazada('Facebook requiere revisión manual; no duplicar')
    path=p.parent/d['video'];size=path.stat().st_size
    if not size:raise RuntimeError('MP4 vacío')
    endpoint=FB_PAGE_ID+'/videos'
    if estado=='listo':
        # START no publica; puede dejar una sesión huérfana si se pierde la respuesta.
        print('Facebook: START | bytes:',size,flush=True)
        j=_fb_peticion('POST',endpoint,video=True,data={'upload_phase':'start','file_size':str(size)})
        f=_fb_guardar(p,d,estado='transferencia',session_id=str(j['upload_session_id']),video_id=str(j['video_id']),start=int(j['start_offset']),end=int(j['end_offset']),size=size,error='')
    if f.get('estado')!='transferencia' or f.get('size')!=size:raise RuntimeError('Estado o tamaño de carga Facebook inválido')
    with path.open('rb') as stream:
        while f['start']!=f['end']:
            a,b=f['start'],f['end']
            if not 0<=a<b<=size:raise RuntimeError('Offsets Meta inválidos')
            stream.seek(a);chunk=stream.read(b-a)
            if len(chunk)!=b-a:raise RuntimeError('MP4 incompleto')
            j=_fb_peticion('POST',endpoint,video=True,data={'upload_phase':'transfer','upload_session_id':f['session_id'],'start_offset':str(a)},files={'video_file_chunk':('chunk.mp4',chunk,'application/octet-stream')})
            na,nb=int(j['start_offset']),int(j['end_offset'])
            if na<=a or not 0<=na<=nb<=size:raise RuntimeError('Meta no avanzó la transferencia; revisar sesión')
            f=_fb_guardar(p,d,start=na,end=nb)
            print(f'Facebook: transferencia {na*100//size}%',flush=True)
    if f['start']!=size:raise RuntimeError('Transferencia Facebook incompleta')
    descripcion=descripcion_youtube(d['caso'],d['fuentes'],d['creditos'])
    # Persistir antes del único FINISH que puede crear la publicación pública.
    print('Facebook: FINISH | ID:',f['video_id'],flush=True)
    f=_fb_guardar(p,d,estado='fin_incierto')
    j=_fb_peticion('POST',endpoint,video=True,data={'upload_phase':'finish','upload_session_id':f['session_id'],'title':d['caso']['titulo'],'description':descripcion,'published':'true','no_story':'false','hide_from_newsfeed':'false'})
    if j.get('success') is not True:raise PublicacionAplazada('Facebook: respuesta FINISH no confirmada; reconciliar ID antes de repetir')
    _fb_guardar(p,d,estado='enviado',error='')
    print('Facebook: FINISH aceptado; publicación aún no confirmada',flush=True)
    for intento in range(4):
        try:return _fb_verificar_video(p,d)
        except PublicacionAplazada:
            if intento==3:raise
            time.sleep(10)



# Deus Digitalis 5.3: SOLO episodios NUEVOS en ejecuciones normales.
# Los manifiestos antiguos permanecen intactos, pero jamás se reanudan ni
# consumen cupo. El mismo MP4 nuevo se intenta enviar a AMBAS plataformas
# durante la MISMA ejecución, independientemente de que una de ellas falle.
# Las peticiones no son atómicas: cada API confirma su publicación por separado.
NUMEN_SOLO_EPISODIOS_NUEVOS = True
NUMEN_SINCRONIZAR_EPISODIOS = False

def _numen_comprobar_mp4_16_9(path, d=None, guardar=None):
    """Comprueba el archivo maestro y su huella antes de cualquier nueva subida."""
    path=Path(path)
    if not path.is_file() or path.stat().st_size<=0:
        raise PublicacionAplazada('MP4 maestro no disponible: '+str(path))
    try:
        cp=subprocess.run(['ffprobe','-v','error','-select_streams','v:0',
              '-show_entries','stream=width,height,sample_aspect_ratio,display_aspect_ratio,side_data_list:stream_tags=rotate',
              '-of','json',str(path)],capture_output=True,text=True,timeout=40,check=True)
        video=(json.loads(cp.stdout).get('streams') or [])[0]
    except (OSError,subprocess.SubprocessError,ValueError,IndexError,KeyError) as exc:
        raise PublicacionAplazada('No se pudo validar el formato MP4 mediante ffprobe: '+type(exc).__name__) from exc
    w,h=int(video.get('width',0)),int(video.get('height',0))
    rot=int(float((video.get('tags') or {}).get('rotate',0)))
    for sd in video.get('side_data_list') or []:
        if sd.get('rotation') is not None:rot=int(float(sd['rotation']))
    sar=str(video.get('sample_aspect_ratio') or '1:1')
    dar=str(video.get('display_aspect_ratio') or '16:9')
    if (w,h)!=(1920,1080) or rot%180!=0 or sar not in ('1:1','1/1') or dar not in ('16:9','1920:1080'):
        raise PublicacionAplazada(f'MP4 no horizontal 1920x1080 SAR 1:1: {w}x{h}, rotación {rot}, SAR {sar}, DAR {dar}')
    digest=hashlib.sha256()
    with path.open('rb') as stream:
        for chunk in iter(lambda:stream.read(2**20),b''):digest.update(chunk)
    huella=digest.hexdigest()
    if d is not None:
        anterior=d.get('mp4_sha256')
        if anterior and anterior!=huella:raise PublicacionAplazada('MP4 cambió respecto del manifiesto; revisar antes de publicar')
        if not anterior and guardar is not None:
            d['mp4_sha256']=huella
            d['formato_mp4']='1920x1080;16:9;SAR1:1'
            _cola_json(guardar,d)
    print('MP4 maestro 16:9 verificado | 1920x1080 | SHA256',huella[:14],flush=True)
    return huella


def _dual_pendiente(d):
    return (PUBLICAR_EN_YOUTUBE and d.get('estado')!='publicado') or (PUBLICAR_EN_FACEBOOK and ('facebook' in d or d.get('estado')!='publicado') and d.get('facebook',{}).get('estado')!='publicado')


# Presupuestos independientes: una subida Facebook y una reconciliación Facebook por ejecución.
# Consultar un ID previo nunca consume el cupo de subida de un MP4 nuevo.
_DUAL_USADO=set()
_DUAL_BLOQUEADO=set()

def _medio_valido(path,d,k):
    path=Path(path)
    if not path.is_file() or path.stat().st_size<=0:return False
    if k=='video':
        expected=(d.get('facebook') or {}).get('size') or d.get('video_bytes')
        if expected and path.stat().st_size!=int(expected):return False
    return True


def _medios_faltantes(p,d,keys=('video','miniatura','srt')):
    faltan=[]
    for k in keys:
        nombre=d[k]
        if Path(nombre).name!=nombre:raise RuntimeError('Nombre de medio inválido en cola')
        target=p.parent/nombre
        if _medio_valido(target,d,k):continue
        original=Path(d.get('carpeta_original') or OUTPUT_BASE/d['episodio']['id'])/nombre
        if original.resolve()!=target.resolve() and _medio_valido(original,d,k):
            shutil.copy2(original,target)
            print('Cola: medio restaurado desde carpeta original |',d['episodio']['id'],nombre,flush=True)
        else:faltan.append(k)
    return faltan


def _restaurar_medios_artifactos():
    if NUMEN_SOLO_EPISODIOS_NUEVOS:
        print('Modo solo nuevos: no se restauran MP4 de episodios históricos.',flush=True)
        return
    # Solo restaurar medios exactos de manifiestos actuales, nunca JSON antiguos.
    import tempfile,zipfile
    pendientes=[(p,d) for p,d in _cola_manifiestos() if _dual_pendiente(d)]
    def faltantes():
        return [(p,d,k) for p,d in pendientes for k in _medios_faltantes(p,d)]
    missing=faltantes()
    if not missing:
        print('Cola: todos los medios pendientes disponibles',flush=True);return
    repo=os.getenv('GITHUB_REPOSITORY','')
    if not repo or not os.getenv('GH_TOKEN'):
        print('Cola: sin acceso a artefactos GitHub; conservar manifiestos',flush=True);return
    try:
        raw=subprocess.check_output(['gh','api',f'repos/{repo}/actions/artifacts?per_page=100'],timeout=45)
        arts=[a for a in json.loads(raw).get('artifacts',[]) if not a.get('expired') and re.fullmatch(r'numenexcodice-\d+-\d+',a.get('name',''))]
    except Exception as exc:
        print('Cola: no se pudo listar artefactos |',type(exc).__name__,flush=True);return
    # Buscar primero la ejecución manual indicada, si existe, después las recientes.
    prefer=os.getenv('NUMEN_RESTORE_RUN_ID','').strip()
    arts.sort(key=lambda a:(bool(prefer and str((a.get('workflow_run') or {}).get('id'))==prefer),a.get('created_at','')),reverse=True)
    for a in arts[:5]:
        if not missing:break
        try:
            with tempfile.TemporaryDirectory() as td:
                archive=Path(td)/'respaldo.zip'
                with archive.open('wb') as out:
                    subprocess.run(['gh','api',f'repos/{repo}/actions/artifacts/{int(a["id"])}/zip'],stdout=out,check=True,timeout=180)
                with zipfile.ZipFile(archive) as z:
                    names=set(z.namelist())
                    for p,d,k in missing:
                        name=d[k]; eid=d['episodio']['id']; target=p.parent/name
                        if _medio_valido(target,d,k):continue
                        candidates=[f'state/pendientes_youtube/{eid}/{name}',f'output/NumenExCodice/{eid}/{name}',f'pendientes_youtube/{eid}/{name}']
                        member=next((n for n in candidates if n in names),None)
                        if not member:continue
                        info=z.getinfo(member)
                        if info.file_size<=0:continue
                        tmp=target.with_name(target.name+'.restore-tmp')
                        try:
                            with z.open(info) as r,tmp.open('wb') as w:shutil.copyfileobj(r,w)
                            if _medio_valido(tmp,d,k):
                                os.replace(tmp,target)
                                print('Cola: recuperado de artefacto |',eid,name,a['name'],flush=True)
                        finally:tmp.unlink(missing_ok=True)
        except Exception as exc:print('Cola: artefacto no restaurado |',a.get('name'),type(exc).__name__,flush=True)
        missing=faltantes()
    for p,d,k in missing:print('Cola: medio no recuperado; manifiesto conservado |',d['episodio']['id'],d[k],flush=True)


def _dual_intento(p,d,historial):
    # Registrar intención Facebook ANTES de YouTube, para conservar el MP4.
    if PUBLICAR_EN_FACEBOOK and 'facebook' not in d and d.get('estado')!='publicado':
        _fb_guardar(p,d,estado='listo',page_id=FB_PAGE_ESPERADA)
    yt_existente=PUBLICAR_EN_YOUTUBE and any(r.get('episodio')==d['episodio']['id'] and r.get('youtube_id') for r in leer_historial(historial))
    yt_faltantes=_medios_faltantes(p,d) if PUBLICAR_EN_YOUTUBE and d.get('estado') in ('listo','limite') and not yt_existente else []
    if yt_faltantes:print('YouTube: medios faltantes; no consume cupo |',d['episodio']['id'],','.join(yt_faltantes),flush=True)
    if not yt_faltantes and PUBLICAR_EN_YOUTUBE and d.get('estado')!='publicado' and (d.get('estado')!='intento_incierto' or yt_existente) and 'yt' not in _DUAL_USADO and 'yt' not in _DUAL_BLOQUEADO and time.time()>=d.get('reintentar_desde',0):
        _DUAL_USADO.add('yt')
        try:
            if d.get('estado') in ('listo','limite') and time.time()>=d.get('reintentar_desde',0):
                _numen_comprobar_mp4_16_9(p.parent/d['video'],d,p)
                validar_canal_youtube(youtube_servicio())
            _cola_intento(p,d,historial)
        except Exception as exc:print('YouTube pendiente:',str(exc)[:400],flush=True)
    if PUBLICAR_EN_FACEBOOK and 'facebook' in d:
        f=d['facebook']; estado=f.get('estado','listo')
        cupo='fb_verificar' if estado in ('enviado','fin_incierto') else 'fb_subir'
        if estado=='revision_manual':
            print('Facebook: revisión manual requerida |',d['episodio']['id'],flush=True)
        elif estado!='publicado':
            if NUMEN_SINCRONIZAR_EPISODIOS and PUBLICAR_EN_YOUTUBE and d.get('estado')!='publicado' and cupo=='fb_subir':
                print('Facebook: espera al mismo episodio confirmado en YouTube |',d['episodio']['id'],flush=True)
            elif time.time()<f.get('reintentar_desde',0):
                print('Facebook: reintento diferido |',d['episodio']['id'],flush=True)
            elif cupo=='fb_subir' and _medios_faltantes(p,d,('video',)):
                print('Facebook: MP4 faltante; no consume cupo |',d['episodio']['id'],flush=True)
            elif cupo in _DUAL_USADO:
                print('Facebook: en cola; cupo de '+cupo+' utilizado |',d['episodio']['id'],flush=True)
            else:
                _DUAL_USADO.add(cupo)
                print('Facebook: '+('verificar ID anterior' if cupo=='fb_verificar' else 'subir/reanudar MP4')+' |',d['episodio']['id'],flush=True)
                try:
                    if cupo=='fb_subir' and estado=='listo':
                        _numen_comprobar_mp4_16_9(p.parent/d['video'],d,p)
                    _fb_intento(p,d)
                except Exception as exc:
                    f=d['facebook']; n=int(f.get('fallos_consecutivos',0))+1
                    estado=f.get('estado','listo')
                    # Nunca reiniciar automáticamente una carga cuyo FINISH pudo publicarse.
                    if n>=3 and estado in ('enviado','fin_incierto','transferencia'):
                        estado='revision_manual'
                    _fb_guardar(p,d,estado=estado,fallos_consecutivos=n,reintentar_desde=time.time()+min(86400,900*2**min(n,6)),error=str(exc)[:400])
                    print('Facebook pendiente:',str(exc)[:400],flush=True)
    if PUBLICAR_EN_YOUTUBE and d.get('estado') in ('listo','limite'):
        print('YouTube: en cola |',('límite del canal' if 'yt' in _DUAL_BLOQUEADO or d.get('estado')=='limite' else 'cupo de ejecución o reintento pendiente'), '|',d['episodio']['id'],flush=True)
    print('Estado plataformas | YouTube:',d.get('estado'),'| Facebook:',d.get('facebook',{}).get('estado','no solicitado'),flush=True)
    if not _dual_pendiente(d):
        # No borrar medios mientras haya una plataforma pendiente, aunque esté deshabilitada.
        if d.get('estado')=='publicado' and d.get('facebook',{}).get('estado','publicado')=='publicado':
            original=Path(d.get('carpeta_original',''))
            if original.resolve()!=p.parent.resolve() and all((original/d[k]).is_file() for k in ('video','miniatura','srt')):
                for archivo in ('PUBLICACION_FACEBOOK.json','PUBLICACION_YOUTUBE.json','DECLARACION_IA_YOUTUBE.json','MINIATURA_YOUTUBE.json','PRIVACIDAD_YOUTUBE.json'):
                    if (p.parent/archivo).is_file():shutil.copy2(p.parent/archivo,original/archivo)
                datos=leer_historial(historial)
                for r in datos:
                    if r.get('episodio')==d['episodio']['id']:r['salida']=str(original/d['video'])
                _cola_json(historial,datos)
            for k in ('video','miniatura','srt'):(p.parent/d[k]).unlink(missing_ok=True)
        return True
    return False


def _dual_publicar(video,thumb,srt,caso,episodio,fuentes,creditos,carpeta,historial):
    _numen_comprobar_mp4_16_9(video)
    p=AERO_COLA_DIR/episodio['id']/'pendiente.json'
    if p.exists():raise PublicacionAplazada('Ya existe la cola '+str(p))
    p.parent.mkdir(parents=True,exist_ok=True)
    for archivo in (video,thumb,srt):shutil.copy2(archivo,p.parent/Path(archivo).name)
    d={'estado':'listo','nicho':NICHO,'canal_id':YT_CANAL_ESPERADO,'carpeta_original':str(carpeta),'privacidad':YOUTUBE_PRIVACY,'video':Path(video).name,'miniatura':Path(thumb).name,'srt':Path(srt).name,'caso':{k:v for k,v in caso.items() if not k.startswith('_') or k in ('_titulo_caso','_universal')},'episodio':episodio,'fuentes':fuentes,'creditos':creditos,'creado_utc':datetime.now(timezone.utc).isoformat(),'video_bytes':Path(video).stat().st_size}
    if PUBLICAR_EN_FACEBOOK:d['facebook']={'estado':'listo','page_id':FB_PAGE_ESPERADA}
    _cola_json(p,d)
    return _dual_intento(p,d,historial)


def _dual_reanudar(historial):
    if NUMEN_SOLO_EPISODIOS_NUEVOS:
        print('Modo solo nuevos: cola histórica ignorada, sin reintentos.',flush=True)
        return False
    activos=[(p,d) for p,d in _cola_manifiestos() if _dual_pendiente(d)]
    if any(d.get('nicho')!=NICHO for _,d in activos):
        raise PublicacionAplazada('Cola de otro nicho; revisar manualmente')
    activos.sort(key=lambda x:(x[1].get('creado_utc',''),str(x[0])))
    if any(d.get('estado')=='limite' and time.time()<d.get('reintentar_desde',0) for _,d in activos):
        _DUAL_BLOQUEADO.add('yt');print('YouTube: límite del canal aún vigente',flush=True)
    if NUMEN_SINCRONIZAR_EPISODIOS:
        # El manifiesto antiguo en revisión manual se conserva: no se reenvía.
        # Para avanzar con la deuda histórica de YouTube, se puede procesar
        # un episodio posterior; nunca otra pareja en esta misma ejecución.
        candidatos=[(p,d) for p,d in activos if not (
             d.get('estado')=='publicado' and
             d.get('facebook',{}).get('estado')=='revision_manual')]
        if candidatos:
            p,d=candidatos[0]
            print('Cola maestra | episodio:',d['episodio']['id'],
                  '| un mismo MP4 para YouTube y Facebook',flush=True)
            _dual_intento(p,d,historial)
        if any(d.get('facebook',{}).get('estado')=='revision_manual' for _,d in activos):
            print('Cola maestra: existe Facebook en revisión manual; no se duplica',flush=True)
    else:
        for p,d in activos:_dual_intento(p,d,historial)
    restantes=sum(_dual_pendiente(d) for _,d in _cola_manifiestos())
    maximo=max(1,int(os.getenv('NUMEN_MAX_PENDIENTES','20')))
    print(f'Cola maestra: {restantes} pendientes / máximo {maximo}',flush=True)
    if restantes>=maximo:
        _cola_json(OUTPUT_BASE/'ULTIMO_INFORME_EJECUCION.json',{'estado':'cola_llena','pendientes':restantes})
        return True
    if NUMEN_SINCRONIZAR_EPISODIOS and activos:
        print('Sincronización: sesión dedicada a la cola histórica; no se genera otro video hoy.',flush=True)
        return True
    return False


def _fb_recuperar(historial):
    if not PUBLICAR_EN_FACEBOOK or not PERMITIR_PUBLICACION_SIN_REVISION:raise RuntimeError('Facebook no autorizado')
    vid=os.getenv('FB_RECUPERAR_ID','').strip()
    if not vid.isdigit() or os.getenv('FB_CONFIRMAR_AUSENCIA','').lower()!='true':raise RuntimeError('Indicar ID anterior y confirmar ausencia en Business Suite')
    matches=[(p,d) for p,d in _cola_manifiestos() if str(d.get('facebook',{}).get('video_id'))==vid]
    if len(matches)!=1:raise RuntimeError('ID anterior no coincide con exactamente un pendiente')
    p,d=matches[0];f=d['facebook']
    if d.get('nicho')!=NICHO or f.get('page_id')!=FB_PAGE_ESPERADA or f.get('estado') not in ('enviado','fin_incierto','revision_manual','transferencia'):
        raise RuntimeError('Estado no elegible para recuperación')
    _fb_preflight()
    # Si el objeto responde, no se autoriza una nueva carga por esta vía.
    try:j=_fb_peticion('GET',vid,params={'fields':'id'})
    except FacebookAPIError as exc:
        if (exc.code,exc.subcode)!=(100,33):raise
    else:raise RuntimeError('ID anterior todavía accesible; no se repite la carga')
    item,edge=_fb_buscar_video(vid)
    if item:raise RuntimeError('ID anterior localizado; no se repite la carga')
    faltan=_medios_faltantes(p,d,('video',))
    if faltan:raise RuntimeError('Falta MP4 pendiente; restaurar artefacto antes de recuperar')
    anteriores=list(f.get('recuperaciones',[]))
    if any(str(x.get('video_id'))==vid for x in anteriores):raise RuntimeError('Recuperación anterior ya registrada')
    anteriores.append({'video_id':vid,'estado':f.get('estado'),'utc':datetime.now(timezone.utc).isoformat(),'ausencia_confirmada_operador':True})
    d['facebook']={'estado':'listo','page_id':FB_PAGE_ESPERADA,'recuperaciones':anteriores}
    _fb_guardar(p,d)
    print('Facebook: recuperación manual autorizada del ID',vid,'| reutilizando MP4',flush=True)
    # Solo Facebook: no toca YouTube ni genera otro episodio.
    try:_fb_intento(p,d)
    except Exception as exc:
        _fb_guardar(p,d,error=str(exc)[:400]);print('Facebook recuperación pendiente:',str(exc)[:400],flush=True)
    print('Estado Facebook:',d['facebook']['estado'],flush=True)


def _dual_solo_cola():
    if NUMEN_SOLO_EPISODIOS_NUEVOS:
        print('Modo solo nuevos: --publish-queue deshabilitado; no se publican atrasados.',flush=True)
        return
    if AERO_IA_DRY_RUN or not PERMITIR_PUBLICACION_SIN_REVISION:
        raise RuntimeError('Procesar cola requiere autorización de publicación y no combinar con solo_guion')
    print('Deus Digitalis | motor reflexivo autónomo',VERSION_SCRIPT,'| solo cola',flush=True)
    asegurar_dependencias()
    _dual_reanudar(ruta_historial())
    print('Solo cola: no se genera ni renderiza un episodio nuevo.',flush=True)


def _ent_main():
    if not (OPENROUTER_MODELO=='openrouter/free' or OPENROUTER_MODELO.endswith(':free')):
        raise ValueError('NumenExCodice solo admite modelos gratuitos en OpenRouter.')
    print('Deus Digitalis | motor reflexivo autónomo',VERSION_SCRIPT,flush=True)
    historial=ruta_historial(); memoria=_ent_read(MEMORIA,[])
    if not isinstance(memoria,list):raise ValueError('Memoria inválida: no sobrescribir.')
    cobertura=_ent_cobertura(memoria)
    print(f'Editorial {VERSION_SCRIPT} | {len(memoria)} registros históricos / objetivo {NUMEN_META_EDITORIAL}+ | dimensión prioritaria: {_ent_elegir_dimension(memoria)} | cobertura clasificada: {sum(cobertura.values())}',flush=True)
    asegurar_dependencias()
    if (PUBLICAR_EN_YOUTUBE or PUBLICAR_EN_FACEBOOK) and not AERO_IA_DRY_RUN:
        if not PERMITIR_PUBLICACION_SIN_REVISION:raise RuntimeError('Publicación automática requiere ALLOW_UNREVIEWED_PUBLICATION=true.')
        if NUMEN_SOLO_EPISODIOS_NUEVOS:
            print(f'Publicación {VERSION_SCRIPT} | generar episodio nuevo y enviar el MISMO MP4 a YouTube y Facebook en esta ejecución; cola antigua ignorada.',flush=True)
        elif _dual_reanudar(historial):return
    # A draft survives image/provider failures; keep ID stable for duplicate protection.
    d=_ent_read(BORRADOR,None)
    existentes={r.get('episodio') for r in leer_historial(historial)} | _cola_ids()
    if d and d.get('id') in existentes:
        BORRADOR.unlink(missing_ok=True);d=None
    if d and d.get('perfil_narrativo')!='numen_humano_universal_v46':
        respaldo=BORRADOR.with_name('reflexion_anterior_'+hashlib.sha256(json.dumps(d,sort_keys=True).encode()).hexdigest()[:12]+'.json')
        _cola_json(respaldo,d)
        print('Borrador anterior respaldado; se generará con la nueva personalidad.',flush=True)
        d=None
    if d:
        try:
            _ent_diversidad_refs(d,d.get('revision_tematica'),memoria)
        except ValueError as exc:
            respaldo=BORRADOR.with_name('reflexion_anterior_'+hashlib.sha256(json.dumps(d,sort_keys=True).encode()).hexdigest()[:12]+'.json')
            _cola_json(respaldo,d)
            print(f'Borrador anterior respaldado. Se renovará tras la revisión de identidad: {exc}',flush=True)
            d=None
    if not d:
        metricas=[]
        if os.getenv('YT_ANALYTICS_REFRESH_TOKEN') and PUBLICAR_EN_YOUTUBE and not AERO_IA_DRY_RUN:
            try:metricas=_viral_consultar_historico_analytics() or []
            except Exception as e:print('Analytics opcional:',type(e).__name__,flush=True)
        d=_ent_generar(memoria,metricas)
        d['perfil_narrativo']='numen_humano_universal_v46'
        d['id']='ent-'+hashlib.sha256(_univ_normalizar(d['titulo']+' '+d['tesis']).encode()).hexdigest()[:16]
        if d['id'] in existentes:raise EpisodioRecuperable('ID ya registrado.')
        _cola_json(BORRADOR,d)
        PROGRESO_EDITORIAL.unlink(missing_ok=True)
    subtitulo=_ent_subtitulo(d)
    if d.get('mini_subtitulo')!=subtitulo:
        d['mini_subtitulo']=subtitulo;_cola_json(BORRADOR,d)
    resumen=_ent_resumen_publicacion(d)
    if d.get('resumen_publicacion')!=resumen:
        d['resumen_publicacion']=resumen;_cola_json(BORRADOR,d)
    print('Miniatura | subtítulo temático:',subtitulo,flush=True)
    eid=d['id']; carpeta=OUTPUT_BASE/eid;carpeta.mkdir(parents=True,exist_ok=True)
    _cola_json(carpeta/'REFLEXION.json',d)
    if AERO_IA_DRY_RUN: print('GUION GUARDADO, sin publicación:',carpeta);return
    caso={'titulo':d['titulo'],'_titulo_caso':d['titulo'],'categoria':d['categoria'],'estado':'Reflexión filosófica de personaje artificial','tesis':d['tesis'],'resumen_publicacion':d['resumen_publicacion'],'escenas':d['escenas'],'pregunta':d['pregunta'],'mini_titulo':d['mini_titulo'].upper(),'_mini_subtitulo':d['mini_subtitulo']}
    episodio={'id':eid,'caso_id':eid,'titulo':d['titulo']}
    plan=[('gancho' if i==0 else 'conclusion' if i==len(d['escenas'])-1 else 'desarrollo',e['texto']) for i,e in enumerate(d['escenas'])]+[('cta',_ent_cta_rotativo(eid))]
    fotos,creditos,mapa=_ent_fotos(d,carpeta);caso['_mapa_visual']=mapa
    thumb=miniatura(caso,[Path(mapa[0])],carpeta)
    bloques,cues,voz=generar_voces(plan,carpeta)
    inicio=next((b['inicio'] for b in bloques if b['tipo']=='cta'),None)
    srt,ass=subtitulos(cues,carpeta,inicio_cta=inicio)
    print(f'Voz femenina: {VOZ} | ritmo {VELOCIDAD} | tono {TONO_VOZ} | reverb templo 1.50s + delay estéreo 165/205ms',flush=True)
    audio=mezclar_cinematica(reverberar_narracion(voz,carpeta),carpeta)
    guardar_metadatos(caso,bloques,[],creditos,carpeta)
    # Un solo plano de narración evita reiniciar el zoom entre escenas.
    video_bloques=_numen_bloques_visuales(bloques)
    base=renderizar_clips(video_bloques,fotos,caso,carpeta);video=finalizar_video(base,audio,ass,carpeta,caso)
    # Store editorial memory before publication so the next episode can reason from it.
    if eid not in {m.get('id') for m in memoria}:
        memoria.append(dict({k:d[k] for k in ('id','titulo','tesis','categoria','pregunta','dimension','enfoque_distintivo','ejemplo_central','conclusion') if k in d},autorreferencias=d['revision_tematica']['autorreferencias']));_cola_json(MEMORIA,memoria)
    if PUBLICAR_EN_YOUTUBE or PUBLICAR_EN_FACEBOOK:
        print('Publicación de pareja NUEVA | episodio:',eid,'| archivo:',Path(video).name,'| ambos destinos en la misma ejecución',flush=True)
        completo=_dual_publicar(video,thumb,srt,caso,episodio,[],creditos,carpeta,historial)
        _cola_json(OUTPUT_BASE/'ULTIMO_INFORME_EJECUCION.json',{'estado':'publicado' if completo else 'publicacion_aplazada','episodio':eid})
    else:anotar_historial(historial,{'episodio':eid,'titulo':d['titulo'],'salida':str(video),'estado':'generado_local'})
    BORRADOR.unlink(missing_ok=True)
    print('NumenExCodice | video terminado:',video,flush=True)


def _ent_test_recuperacion_59():
    from unittest.mock import patch
    import tempfile, copy
    base='Una persona espera una llamada importante, mira la pantalla y duda entre seguir pendiente o continuar con sus tareas. '
    # 9 escenas x 43 palabras aproximadamente = 390; evitar identidades externas.
    texto=' '.join([base]*3).strip()
    escenas=[{'texto':texto} for _ in range(9)]
    # ajustar borrador para rango 350–449 y extensión de escenas equilibrada
    for e in escenas:e['texto']=' '.join(e['texto'].split()[:43])+'.'
    enfoque={'pregunta':'¿Qué cambia cuando esperamos una llamada importante?',
             'ejemplo_central':'una persona espera una llamada mientras intenta terminar sus tareas'}
    d={'titulo':'Una llamada y nuestra atención','escenas':escenas}
    assert 350<=sum(len(x['texto'].split()) for x in escenas)<450
    salvado=_ent_recuperar_borrador_corto(copy.deepcopy(d),enfoque)
    _ent_balance_eficiente(salvado)
    assert sum(len(x['texto'].split()) for x in salvado['escenas'])>=450
    assert [x['texto'] for x in d['escenas']]==[x['texto'] for x in escenas]
    try:_ent_recuperar_borrador_corto({'escenas':[{'texto':'breve'} for _ in range(9)]},enfoque)
    except ValueError:pass
    else:raise AssertionError('Se recuperó un guion de solo nueve palabras')
    print('OK 6.1: rescate extractivo de borradores cortos, equilibrio y sin consultas remotas',flush=True)


